/* Motor Analítico Canvas Nativo (HU-16 y HU-17 - Sin Dependencia Externa) */
class Chart {
    constructor(canvas, config) {
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        const w = canvas.width = canvas.parentElement.clientWidth || 500;
        const h = canvas.height = 240;
        const pad = { top: 30, right: 20, bottom: 35, left: 45 };
        const plotW = w - pad.left - pad.right;
        const plotH = h - pad.top - pad.bottom;

        const labels = config.data.labels || [];
        const datasets = config.data.datasets || [];
        let maxVal = 10;
        datasets.forEach(ds => ds.data.forEach(v => { if (v > maxVal) maxVal = v; }));
        maxVal = Math.ceil(maxVal * 1.2);

        ctx.clearRect(0, 0, w, h);
        ctx.font = '11px Segoe UI, sans-serif';

        // Ejes y cuadrícula
        ctx.strokeStyle = '#ecf0f1';
        ctx.fillStyle = '#7f8c8d';
        for (let i = 0; i <= 4; i++) {
            const y = pad.top + (plotH / 4) * i;
            const val = Math.round(maxVal - (maxVal / 4) * i);
            ctx.beginPath(); ctx.moveTo(pad.left, y); ctx.lineTo(w - pad.right, y); ctx.stroke();
            ctx.fillText(val, 8, y + 4);
        }

        const stepX = plotW / Math.max(labels.length, 1);

        // Etiquetas del eje X
        labels.forEach((lbl, idx) => {
            const x = pad.left + idx * stepX + stepX / 2;
            ctx.fillStyle = '#34495e';
            ctx.textAlign = 'center';
            ctx.fillText(lbl, x, h - 10);
        });

        // Dibujo de Barras (HU-16) o Líneas (HU-17)
        if (config.type === 'bar') {
            const barW = (stepX * 0.7) / Math.max(datasets.length, 1);
            datasets.forEach((ds, dIdx) => {
                ctx.fillStyle = ds.backgroundColor || '#3498db';
                ds.data.forEach((val, idx) => {
                    const barH = (val / maxVal) * plotH;
                    const x = pad.left + idx * stepX + (stepX * 0.15) + dIdx * barW;
                    const y = pad.top + plotH - barH;
                    ctx.fillRect(x, y, barW - 2, barH);
                });
            });
        } else if (config.type === 'line') {
            datasets.forEach(ds => {
                ctx.strokeStyle = ds.borderColor || '#e74c3c';
                ctx.lineWidth = 3;
                ctx.beginPath();
                ds.data.forEach((val, idx) => {
                    const x = pad.left + idx * stepX + stepX / 2;
                    const y = pad.top + plotH - (val / maxVal) * plotH;
                    if (idx === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                });
                ctx.stroke();

                ds.data.forEach((val, idx) => {
                    const x = pad.left + idx * stepX + stepX / 2;
                    const y = pad.top + plotH - (val / maxVal) * plotH;
                    ctx.fillStyle = '#e74c3c';
                    ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI * 2); ctx.fill();
                });
            });
        }

        // Leyenda superior
        let legX = pad.left;
        datasets.forEach(ds => {
            ctx.fillStyle = ds.backgroundColor || ds.borderColor || '#3498db';
            ctx.fillRect(legX, 8, 12, 12);
            ctx.fillStyle = '#2c3e50';
            ctx.textAlign = 'left';
            ctx.fillText(ds.label || '', legX + 16, 18);
            legX += 140;
        });
    }
}